theme.css:
#wemd{color:#3d3028;background-color:#faf6f0;font-family:Georgia, 'Noto Serif SC', 'Source Han Serif SC', serif;font-size:17px;line-height:1.9;letter-spacing:0.01em;text-align:justify;padding:36px 28px;overflow-wrap:anywhere}
#wemd p{margin:0 0 1.4em;text-indent:2em}
#wemd h1{font-size:26px;font-weight:400;color:$colors.text_primary;margin-top:2.2em;margin-bottom:1.2em;text-align:center}
#wemd h2{font-size:21px;font-weight:600;color:$colors.text_primary;margin-top:1.8em;margin-bottom:0.8em;text-align:left;border-bottom:1px solid $colors.border;padding-bottom:.4em}
#wemd h3{font-size:18px;font-weight:600;color:$colors.accent;margin-top:1.5em;margin-bottom:0.6em}
#wemd h3::before{content:"· ";color:#b45309}
#wemd h4{font-size:16px;font-weight:500;color:$colors.text_secondary;margin-top:1.2em;margin-bottom:0.5em}
#wemd blockquote{border-left:4px solid $colors.quote_border;background:$colors.quote_background;padding:16px 22px;color:$colors.text_secondary;font-style:italic;margin:1.2em 0}
#wemd code{background-color:$colors.code_background;color:#92400e;padding:2px 6px;border-radius:4px;font-size:0.9em;font-family:'Fira Code', monospace}
#wemd pre{background:$colors.code_background;border-radius:8px;padding:16px 20px;line-height:1.5;white-space:pre-wrap}
#wemd pre code{background:transparent;padding:0}
#wemd table{width:100%;border-collapse:collapse}
#wemd th, #wemd td{border:1px solid $colors.border;padding:10px 14px}
#wemd th{background:$colors.table_header_bg}
#wemd tr:nth-child(even){background:$colors.table_stripe_bg}
#wemd ul, #wemd ol{padding-left:24px;margin:1em 0}
#wemd ul{list-style-type:disc}
#wemd ol{list-style-type:decimal}
#wemd li{margin-bottom:8px}
#wemd li::marker{color:$colors.accent}
#wemd hr{border:0;border-top:1px solid $colors.border;margin:2.5em 0;width:40%}
#wemd img{max-width:100%;height:auto;border-radius:8px}
#wemd figcaption{font-size:13px;color:$colors.text_secondary;text-align:center}
#wemd a{color:$colors.link_color;text-decoration:underline}
#wemd strong{color:#b45309;font-weight:700}
#wemd mark{background:$colors.highlight_bg;padding:2px 6px;border-radius:4px}
#wemd > p:first-of-type::first-letter{float:left;font-size:2.8em;color:$colors.accent;line-height:1.1;margin-right:.12em}
